3	// Modifiers are percentages OF THE UNMODIFIED BASE PREMIUM, summed additively
4	// rather than compounded — see the spec's integration examples, where a cursed
5	// sword is 100 base + 50 curse + 10 first insurance (10% of 100, not of 150).
6	//
7	// Rates are kept as integer percents and divided only once, at the point of
8	// use: percentOf(100, 10) is (100 * 10) / 100 = exactly 10, whereas a 0.1
9	// multiplier would give 10.000000000000002 and inflate Math.ceil.
10	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
11	
12	const FIRST_INSURANCE_PERCENT = 10;
13	const CURSE_PERCENT = 50;
14	
15	// The price list prices each main item individually...
16	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	};
22	
23	// ...whereas every component is flat-rated at the same base premium,
24	// regardless of which component it is.
25	const COMPONENT_BASE_PREMIUM = 25;
26	const COMPONENT_TYPES = ["rune", "moonstone"];
27	
28	const BLOCK_SIZE = 3;
29	const BLOCK_BASE_PREMIUM = 60;
30	
31	const BASE_PREMIUMS: Record<string, number> = {
32	  ...MAIN_ITEM_BASE_PREMIUMS,
33	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
34	};
35	
36	type Item = { type: string; cursed?: boolean };
37	type Step = { items: Item[] };
38	type Scenario = { steps: Step[] };
39	
40	const countByType = (items: Item[]): Map<string, number> =>
41	  items.reduce(
42	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
43	    new Map<string, number>(),
44	  );
45	
46	// A building block of exactly 3 alike components is offered at a special
47	// rate; any other count is priced per component.
48	const basePremiumForType = (type: string, count: number): number =>
49	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
50	
51	const stepBasePremium = (step: Step): number =>
52	  [...countByType(step.items)].reduce(
53	    (total, [type, count]) => total + basePremiumForType(type, count),
54	    0,
55	  );
56	
57	// Item-specific modifiers apply to the base premium of the affected item,
58	// so they are computed per item rather than from the grouped totals.
59	const itemSurcharges = (items: Item[]): number =>
60	  items.reduce(
61	    (total, item) =>
62	      total + (item.cursed ? percentOf(BASE_PREMIUMS[item.type], CURSE_PERCENT) : 0),
63	    0,
64	  );
65	
66	// Policy-wide modifiers apply to the policy base premium (the sum of all
67	// item base premiums).
68	const policyModifiers = (basePremium: number): number =>
69	  percentOf(basePremium, FIRST_INSURANCE_PERCENT);
70	
71	// Rounded in the MHPCO's favour: premiums round up.
72	const quotePremium = (step: Step): number => {
73	  const basePremium = stepBasePremium(step);
74	
75	  return Math.ceil(
76	    basePremium + itemSurcharges(step.items) + policyModifiers(basePremium) + PROCESSING_FEE,
77	  );
78	};
79	
80	export const runScenario = (scenario: unknown): { results: unknown[] } => {
81	  const { steps } = scenario as Scenario;
82	
83	  const results = steps.map((step) => ({ premium: quotePremium(step) }));
84	
85	  return { results };
86	};
